.eon8-live-page .uk-navbar-left img {
    height: 60px;
    width: auto;
    object-fit: contain;
    transition: height 0.35s ease;
    display: block;
    margin-top:-10px;
}
.eon8-live-page .uk-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    position: relative;
    z-index: 1;
}
.eon8-live-page .uk-navbar-left {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 80px !important;
    flex-wrap: nowrap;
}
.eon8-live-page .uk-navbar-right {
    display: flex !important;
    align-items: center;
    margin-left: auto;
}
.eon8-live-page .uk-navbar-nav > li > .uk-navbar-dropdown {
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important;
}
.eon8-live-page .uk-navbar-nav {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 5px;
    list-style: none;
    margin: 0;
    padding: 0;
}
.eon8-live-page .uk-navbar-nav > li {
    display: flex;
    align-items: center;
    position: relative;
    white-space: nowrap;
}
.eon8-live-page .uk-navbar-nav > li > a {
    display: flex;
    align-items: center;
    padding: 6px 10px;
    font-size: 14px;
    line-height: 1;
    text-decoration: none;
    position: relative;
}
.eon8-live-page .uk-navbar-nav > li > a::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    transform: scaleX(0);
    transition: transform 0.3s ease;
    transform-origin: left;
}
.eon8-live-page .uk-navbar-nav > li > a:hover::after {
    transform: scaleX(1);
}
@media (max-width: 1024px) {.eon8-live-page .uk-navbar-left img {
        height: 50px;
    }
.eon8-live-page .uk-navbar-nav {
        gap: 5px;
    }}
@media (max-width: 768px) {.eon8-live-page .uk-navbar-left img {
        height: 45px;
    }
.eon8-live-page .uk-navbar-nav {
        display: none !important;
    }}
@media (max-width: 480px) {.eon8-live-page .uk-navbar-left img {
        height: 38px;
    }}
.eon8-live-page .meta-hero {
    padding: 60px 20px;
    text-align: left;

    color: #fff;
    font-family: Arial, sans-serif;
}
.eon8-live-page .meta-hero h1 {
    font-size: 42px;
    margin-bottom: 20px;
    line-height: 1.3;
    color:#fff;
}
.eon8-live-page .meta-hero p {
    font-size: 18px;
    max-width: 700px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .meta-btn {
    margin-top: 30px;
    display: inline-block;
    padding: 12px 28px;
    background: #fff;
    color: #000;
    border-radius: 30px;
    text-decoration: none;
    font-weight: bold;
    transition: 0.3s;
}
.eon8-live-page .meta-btn:hover {
    background: #fff0;
}
.eon8-live-page .arnexto-section {
    padding: 0px 20px;

    font-family: Arial, sans-serif;
}
.eon8-live-page .arnexto-container {
    max-width: 1200px;
    margin: auto;
}
.eon8-live-page .arnexto-header {
    text-align: center;
    margin-bottom: 60px;
}
.eon8-live-page .arnexto-header h2 {
    font-size: 34px;
    color: #ea580c;
    margin-bottom: 10px;
}
.eon8-live-page .arnexto-header p {
    font-size: 16px;
    color: #555;
    max-width: 850px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .arnexto-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 30px;
}
.eon8-live-page .arnexto-card {
    background: linear-gradient(135deg, #fb923c, #ea580c);
    color: #fff;
    padding: 30px;
    border-radius: 18px;
    box-shadow: 0 12px 30px rgba(251,146,60,0.3);
    transition: 0.3s ease;
}
.eon8-live-page .arnexto-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 18px 40px rgba(251,146,60,0.45);
}
.eon8-live-page .arnexto-icon {
    font-size: 28px;
    margin-bottom: 15px;
    color: #fff7ed;
}
.eon8-live-page .arnexto-title {
    font-size: 20px;
    font-weight: bold;
    margin-bottom: 10px;
}
.eon8-live-page .arnexto-desc {
    font-size: 14px;
    color: #fff7ed;
    line-height: 1.7;
}
.eon8-live-page .arnexto-footer {
    text-align: center;
    margin-top: 60px;
    font-size: 17px;
    font-weight: 500;
    color: #333;
}
.eon8-live-page .arecom-section {
    padding: 0px 20px;
    background: #fff7ed;
    font-family: Arial, sans-serif;
}
.eon8-live-page .arecom-container {
    max-width: 1360px;
    margin: auto;
}
.eon8-live-page .arecom-header {
    text-align: center;
    margin-bottom: 60px;
}
.eon8-live-page .arecom-header h2 {
    font-size: 32px;
    color: #ea580c;
    margin-bottom: 10px;
}
.eon8-live-page .arecom-header p {
    font-size: 16px;
    color: #555;
    max-width: 800px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .arecom-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 25px;
}
.eon8-live-page .arecom-card {
    background: #ffffff;
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 10px 25px rgba(234,88,12,0.12);
    transition: 0.3s ease;
}
.eon8-live-page .arecom-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 18px 35px rgba(234,88,12,0.25);
}
.eon8-live-page .arecom-card img {
    width: 100%;
    height: 180px;
    object-fit: cover;
}
.eon8-live-page .arecom-content {
    padding: 20px;
}
.eon8-live-page .arecom-title {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 8px;
    color: #111;
}
.eon8-live-page .arecom-desc {
    font-size: 14px;
    color: #555;
    line-height: 1.6;
}
.eon8-live-page .arlocc-section {
    padding: 0px 20px;

    font-family: Arial, sans-serif;
}
.eon8-live-page .arlocc-container {
    max-width: 1100px;
    margin: auto;
}
.eon8-live-page .arlocc-header {
    text-align: center;
    margin-bottom: 50px;
}
.eon8-live-page .arlocc-header h2 {
    font-size: 32px;
    color: #ea580c;
    margin-bottom: 10px;
}
.eon8-live-page .arlocc-header p {
    font-size: 16px;
    color: #555;
    max-width: 800px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .arlocc-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 25px;
}
.eon8-live-page .arlocc-card {
    background: #ffffff;
    border-radius: 16px;
    padding: 25px;
    border-left: 4px solid #ea580c;
    box-shadow: 0 10px 25px rgba(234,88,12,0.12);
    transition: 0.3s;
}
.eon8-live-page .arlocc-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 15px 35px rgba(234,88,12,0.25);
}
.eon8-live-page .arlocc-title {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 8px;
    color: #111;
}
.eon8-live-page .arlocc-desc {
    font-size: 14px;
    color: #555;
    line-height: 1.6;
}
.eon8-live-page .arapp-section {
    padding: 0px 20px;
    background: linear-gradient(135deg, #fff7ed, #ffffff);
    font-family: Arial, sans-serif;
}
.eon8-live-page .arapp-container {
    max-width: 1100px;
    margin: auto;
}
.eon8-live-page .arapp-header {
    text-align: center;
    margin-bottom: 60px;
}
.eon8-live-page .arapp-header h2 {
    font-size: 32px;
    color: #ea580c;
    margin-bottom: 10px;
}
.eon8-live-page .arapp-header p {
    font-size: 16px;
    color: #555;
    max-width: 800px;
    margin: auto;
    line-height: 1.7;
}
.eon8-live-page .arapp-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 25px;
}
.eon8-live-page .arapp-card {
    background: #ffffff;
    border-radius: 16px;
    padding: 25px;
    position: relative;
    box-shadow: 0 10px 25px rgba(234,88,12,0.12);
    transition: 0.3s;
    border-top: 4px solid #ea580c;
}
.eon8-live-page .arapp-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 15px 35px rgba(234,88,12,0.25);
}
.eon8-live-page .arapp-number {
    position: absolute;
    top: -15px;
    left: 20px;
    background: #ea580c;
    color: #fff;
    font-size: 14px;
    padding: 6px 12px;
    border-radius: 20px;
    font-weight: bold;
}
.eon8-live-page .arapp-title {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 8px;
    color: #111;
}
.eon8-live-page .arapp-desc {
    font-size: 14px;
    color: #555;
    line-height: 1.6;
}
.eon8-live-page .arfaqo-section {
    padding: 0px 20px;
    background: #ea580c;
    font-family: Arial, sans-serif;
    margin-bottom:30px;
}
.eon8-live-page .arfaqo-container {
    max-width: 900px;
    margin: auto;
}
.eon8-live-page .arfaqo-header {
    text-align: center;
    margin-bottom: 40px;
}
.eon8-live-page .arfaqo-header h2 {
    font-size: 30px;
    color: #ffffff;
}
.eon8-live-page .arfaqo-item {
    background: #ffffff;
    border-radius: 10px;
    margin-bottom: 15px;
    overflow: hidden;
    box-shadow: 0 8px 20px rgba(0,0,0,0.15);
}
.eon8-live-page .arfaqo-question {
    font-size: 17px;
    font-weight: bold;
    cursor: pointer;
    padding: 15px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #111;
    transition: 0.3s;
}
.eon8-live-page .arfaqo-question:hover {
    color: #ea580c;
}
.eon8-live-page .arfaqo-icon {
    font-size: 18px;
    color: #ea580c;
    transition: 0.3s;
}
.eon8-live-page .arfaqo-answer {
    max-height: 0;
    overflow: hidden;
    transition: 0.4s ease;
    padding: 0 20px;
}
.eon8-live-page .arfaqo-answer p {
    font-size: 15px;
    color: #555;
    line-height: 1.6;
    margin-bottom: 15px;
}
.eon8-live-page .arfaqo-item.active .arfaqo-answer {
    max-height: 240px;
}
.eon8-live-page .arfaqo-item.active .arfaqo-icon {
    transform: rotate(45deg);
}
